        { q: "Apakah jenis interaksi apabila kedua-dua organisma mendapat manfaat, seperti burung gembala dan kerbau?", qEn: "What interaction benefits both organisms, like an egret and a buffalo?", options: ["Mutualisme", "Parasitisme", "Komensalisme", "Persaingan"], optionsEn: ["Mutualism", "Parasitism", "Commensalism", "Competition"], correctIndex: 0, explanation: "Dalam mutualisme, kedua-dua pihak mendapat faedah (burung mendapat makanan, kerbau bebas kutu).", explanationEn: "In mutualism, both organisms benefit." },
        { q: "Ikan remora yang menumpang pada ikan jerung untuk mendapat sisa makanan ialah contoh...", qEn: "Remora fish riding on sharks for leftover food is an example of...", options: ["Komensalisme", "Mutualisme", "Parasitisme", "Mangsa-pemangsa"], optionsEn: ["Commensalism", "Mutualism", "Parasitism", "Prey-predator"], correctIndex: 0, explanation: "Komensalisme memberi manfaat kepada satu pihak tanpa memudaratkan perumah.", explanationEn: "Commensalism benefits one organism without harming the host." },
        { q: "Hubungan antara kutu dan anjing ialah contoh...", qEn: "The relationship between ticks and a dog is an example of...", options: ["Parasitisme", "Mutualisme", "Komensalisme", "Simbiosis sihat"], optionsEn: ["Parasitism", "Mutualism", "Commensalism", "Healthy symbiosis"], correctIndex: 0, explanation: "Dalam parasitisme, parasit (kutu) mendapat faedah manakala perumah (anjing) mendapat mudarat.", explanationEn: "In parasitism, the parasite benefits while the host is harmed." },
        { q: "Apakah faktor yang menyebabkan persaingan antara tumbuhan?", qEn: "What factors cause competition among plants?", options: ["Air, cahaya matahari, nutrien dan ruang", "Daging dan tulang", "Pasangan hidup", "Kelajuan angin"], optionsEn: ["Water, sunlight, nutrients, and space", "Meat and bones", "Mates", "Wind speed"], correctIndex: 0, explanation: "Tumbuhan bersaing untuk mendapatkan sumber asas iaitu air, cahaya matahari, nutrien dan ruang.", explanationEn: "Plants compete for water, sunlight, nutrients, and space." },
        { q: "Mengapakah sesetengah haiwan hidup berkumpulan seperti gajah dan lebah?", qEn: "Why do some animals live in groups like elephants and bees?", options: ["Untuk bekerjasama mencari makanan dan melindungi diri daripada musuh", "Supaya mudah dilihat pemangsa", "Supaya makanan cepat habis", "Untuk bersaing sesama sendiri"], optionsEn: ["To cooperate in finding food and protecting against predators", "To be easily spotted by predators", "To finish food faster", "To fight each other"], correctIndex: 0, explanation: "Hidup berkumpulan memudahkan keselamatan dan pencarian makanan.", explanationEn: "Living in groups helps with safety and finding food." },
        { q: "Apakah maksud simbiosis?", qEn: "What does symbiosis mean?", options: ["Hubungan rapat antara dua spesies haiwan atau tumbuhan yang berlainan", "Haiwan yang hidup bersendirian", "Proses tumbuhan membuat makanan", "Kepupusan haiwan"], optionsEn: ["Close relationship between two different species", "Animals living alone", "Process of plants making food", "Extinction of animals"], correctIndex: 0, explanation: "Simbiosis merangkumi mutualisme, komensalisme dan parasitisme.", explanationEn: "Symbiosis includes mutualism, commensalism, and parasitism." },
        { q: "Persaingan antara dua ekor singa jantan untuk merebut kawasan jajahan dikenali sebagai...", qEn: "Competition between two male lions for territory is known as...", options: ["Persaingan intraspesies", "Persaingan interspesies", "Komensalisme", "Mutualisme"], optionsEn: ["Intraspecific competition", "Interspecific competition", "Commensalism", "Mutualism"], correctIndex: 0, explanation: "Persaingan intraspesies berlaku antara organisma daripada spesies yang sama.", explanationEn: "Intraspecific competition occurs among organisms of the same species." },
        { q: "Apakah kelebihan haiwan yang hidup bersendirian seperti harimau?", qEn: "What is an advantage for solitary animals like tigers?", options: ["Mengelakkan persaingan mendapatkan makanan dan kawasan", "Mudah berkongsi sarang", "Sentiasa dibantu kawanan", "Tidak memerlukan wilayah"], optionsEn: ["Avoids competition for food and territory", "Easy to share nests", "Always helped by a herd", "Needs no territory"], correctIndex: 0, explanation: "Haiwan bersendirian tidak perlu berkongsi makanan yang terhad dengan ahli kumpulan lain.", explanationEn: "Solitary animals do not have to share limited food with group members." },
        { q: "Hubungan antara helang dan tikus ialah...", qEn: "The relationship between an eagle and a mouse is...", options: ["Mangsa-pemangsa", "Mutualisme", "Komensalisme", "Parasitisme"], optionsEn: ["Prey-predator", "Mutualism", "Commensalism", "Parasitism"], correctIndex: 0, explanation: "Helang ialah pemangsa yang memburu tikus (mangsa) sebagai makanan.", explanationEn: "The eagle is the predator and the mouse is the prey." },
        { q: "Bagaimanakah persaingan antara anak pokok dalam pasu yang sesak dapat dikurangkan?", qEn: "How can competition among crowded seedlings in a pot be reduced?", options: ["Menjarakkan anak pokok ke pasu berasingan", "Mengurangkan siraman air", "Menutup cahaya matahari", "Menambah lebih banyak biji benih"], optionsEn: ["Spacing the seedlings into separate pots", "Reducing watering", "Blocking sunlight", "Adding more seeds"], correctIndex: 0, explanation: "Penjarangan memberi ruang, air dan nutrien yang mencukupi kepada setiap pokok.", explanationEn: "Spacing gives each plant enough space, water, and nutrients." }
